#include <cstdio>
#include <queue>
using namespace std;

struct Edge {

    int to, cost, time;

    Edge(int to0,int cost0,int time0) {

        to = to0; cost = cost0; time = time0;

    };

};



int nodeCount, edgeCount;



vector<Edge> graph[100];

int distances[100];



void dijkstra(int startNode, int mode)

{

    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> priorityQueue;



    fill(distances, distances + edgeCount, 1e9);

    distances[startNode] = 0;



    priorityQueue.push({0, startNode});



    while (priorityQueue.size()) {

        pair<int, int> p = priorityQueue.top(); priorityQueue.pop();

        int currentNode = p.second;

        for (int i = 0; i < graph[currentNode].size(); ++i) {

            Edge e = graph[currentNode][i];

            int weight = mode == 0 ? e.cost : e.time;

            if (distances[e.to] > distances[currentNode] + weight) {

                distances[e.to] = distances[currentNode] + weight;

                priorityQueue.push({distances[e.to], e.to});

            }

        }

    }

}



int main()

{

    scanf("%d%d", &nodeCount, &edgeCount);

    while (nodeCount || edgeCount) {

        for(int i = 0; i < edgeCount; ++i) graph[i].clear();



        for(int i = 0; i < nodeCount; ++i) {

            int a, b, cost, time; scanf("%d%d%d%d", &a, &b, &cost, &time); a--; b--;

            graph[a].push_back(Edge(b, cost, time));

            graph[b].push_back(Edge(a, cost, time));

        }



        int K; scanf("%d", &K);



        for(int i = 0; i < K; ++i) {

            int p, q, r; scanf("%d%d%d", &p, &q, &r); p--; q--;

            dijkstra(p, r);

            printf("%d\n", distances[q]);

        }

        scanf("%d%d", &nodeCount, &edgeCount);

    }

    return 0;

}

