{

    scanf("%d%d",&N,&M);

    while(N||M) {

        for(int i=0; i < M; ++i) G[i].clear();



        for(int i=0; i < N; ++i) {

            int a,b,cost,time; scanf("%d%d%d%d",&a,&b,&cost,&time); a--; b--;

            G[a].push_back(edge(b,cost,time));

            G[b].push_back(edge(a,cost,time));

        }



        int K; scanf("%d",&K);



        for(int i=0; i < K; ++i) {

            int p,q,r; scanf("%d%d%d",&p,&q,&r); p--; q--;

            dijkstra(p,r);

            printf("%d\n",d[q]);

        }

        scanf("%d%d",&N,&M);

    }

    return 0;

}

